async function saveMaterial(form){const s=findS(ws.id),f=new FormData(form),e=ws.edit&&s.materials.find(m=>m.id===ws.edit),type=e?e.type:String(f.get('type')),m=e||{id:`m-${Date.now()}`,type};m.title=String(f.get('title')).trim();if(!m.title)return toast('Please add a title');if(type==='note'){m.text=String(f.get('text')).trim();if(!m.text)return toast('Write something in the note')}else if(type==='link'){const u=cleanUrl(f.get('url'));if(!u)return toast('Enter a valid link')}else{const file=f.get('file');if(!(file&&file.size)&&!e)return toast('Choose a PDF or image');if(file&&file.size){if(!(file.type==='application/pdf'||file.type.startsWith('image/')))return toast('Only PDF or image files are supported');if(file.size>25*1024*1024)return toast('File is too large (max 25 MB)');try{await idb.put(m.id,file)}catch{return toast('This browser could not store the file')}m.fileName=file.name;m.mime=file.type}}if(type==='link')m.url=cleanUrl(f.get('url'));if(!e)s.materials.push(m);ws.edit=null;save();renderAll();renderWS();toast(e?'Material updated':'Material added')}
function saveVideo(form){const s=findS(ws.id),f=new FormData(form),e=ws.edit&&s.videos.find(v=>v.id===ws.edit),type=String(f.get('type')),title=String(f.get('title')).trim(),url=cleanUrl(f.get('url'));if(!title||!url||!isYT(url))return toast('Enter a title and YouTube link');if(type==='video'&&!ytId(url))return toast('That does not look like a YouTube video link');if(e){e.type=type;e.title=title;e.url=url}else s.videos.push({id:`v-${Date.now()}`,type,title,url});ws.edit=null;save();renderAll();renderWS();toast(e?'Video updated':'Video saved')}
function toggleTask(id){const t=state.tasks.find(x=>x.id===id);if(!t)return;t.done=!t.done;{const d=t.done?todayISO():(t.doneDate||todayISO());state.log[d]=Math.max(0,(state.log[d]||0)+(t.done?1:-1)*Number(t.duration||0));if(t.done)t.doneDate=d}justDone=t.done?t.id:null;if(t.done){updateStreak();if(t.subjectId){const s=findS(t.subjectId);if(s)s.last=Date.now()}}state.focusId=state.tasks.find(x=>!x.done)?.id||null;save();renderAll();if(t.done){burst();toast(state.tasks.some(x=>!x.done)?'✅ Session done. Next one is ready.':'🎉 All sessions done for today!')}else toast('Session reopened');setTimeout(()=>{justDone=null},800)}
function deleteTopic(id){const s=findS(id);if(!s||!confirm(`Delete "${s.topic}"? Its material, videos and topic data will be deleted.`))return;s.materials.filter(m=>m.type==='file').forEach(m=>idb.del(m.id).catch(()=>{}));state.subjects=state.subjects.filter(x=>String(x.id)!==String(id));state.tasks=state.tasks.filter(t=>String(t.subjectId)!==String(id));save();renderAll();toast('Topic deleted')}
function act(a,id){const s=findS(id);if(a==='rate'){const v=prompt(`Rate "${s.topic}" from 1 to 5 stars`,String(s.rating||3));if(v===null)return;s.rating=clamp(Number(v)||3,1,5);save();renderAll();return}if(!s)return;const t=todayISO();if(a==='now'){if(state.onlySubject&&state.onlySubject!==s.subject)state.onlySubject='';s.skip=null;s.postponed=null;state.override={id:s.id,date:t};buildPlan();state.focusId=state.tasks.find(x=>String(x.subjectId)===String(s.id)&&!x.done)?.id;save();renderAll();navigate('focus');}else if(a==='skip'){s.skip=t;if(state.override?.id===s.id)state.override=null;buildPlan();save();renderAll();toast(`${s.topic} skipped for today`)}else if(a==='postpone'){s.postponed=t;s.skip=null;if(state.override?.id===s.id)state.override=null;buildPlan();save();renderAll();toast(`${s.topic} moved down`)}else if(a==='deadline'){const v=prompt('Exam date (YYYY-MM-DD). Leave empty to remove it.',s.exam||'');if(v===null)return;const d=v.trim();if(d&&(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d<todayISO()))return toast('Use a future date like 2026-12-01, or leave empty');s.exam=d;buildPlan();save();renderAll();toast('Deadline updated')} else if(a==='cancel'){if(!confirm(`Archive "${s.topic}"?`))return;s.status='cancelled';buildPlan();save();renderAll();toast('Topic archived')} }
function addTopic(subject){ $('#subjectList').innerHTML=subjectNames().map(n=>`<option value="${esc(n)}">`).join('');$('#modal input[name=subject]').value=typeof subject==='string'?subject:'';$('#modal').classList.add('open');$('#examDateInput').min=todayISO();$('#examDateInput').value='';setTimeout(()=>$(typeof subject==='string'&&subject?'#modal input[name=topic]':'#modal input[name=subject]').focus(),40)}
