async function importBackup(file){try{const d=JSON.parse(await file.text());if(d.app!=='smart-study-planner'||!d.state||!Array.isArray(d.state.subjects))return toast('That file is not a Smart Study Planner backup');if(!confirm('Replace all current data with this backup?'))return;for(const [id,url] of Object.entries(d.files||{}))await idb.put(id,await (await fetch(url)).blob());localStorage.setItem(STORAGE_KEY,JSON.stringify(migrateState(d.state)));location.reload()}catch{toast('Could not read that backup file')}}
