function removeTopics(ids){const set=new Set(ids.map(String));state.subjects.filter(s=>set.has(String(s.id))).forEach(s=>s.materials.forEach(m=>{if(m.type==='file')idb.del(m.id).catch(()=>{})}));state.subjects=state.subjects.filter(s=>!set.has(String(s.id)));state.tasks=state.tasks.filter(t=>!set.has(String(t.subjectId)));if(state.override&&set.has(String(state.override.id)))state.override=null;if(set.has(String(ws.id)))closeModal($('#wsModal'));buildPlan();save();renderAll()}
function subjectAction(a,name){const topics=state.subjects.filter(s=>s.subject===name);if(a==='addtopic')return addTopic(name);
if(a==='rename'){const v=prompt('New subject name',name);if(v===null)return;const n=v.trim().slice(0,50);if(!n||n===name)return;topics.forEach(s=>s.subject=n);if(state.onlySubject===name)state.onlySubject=n;state.tests.forEach(t=>{if(t.subject===name)t.subject=n});state.tasks.forEach(t=>{if(t.subject===name)t.subject=n});save();renderAll();toast(`Renamed to ${n}`)}
else if(a==='delete'){const tests=state.tests.filter(t=>t.subject===name).length;if(!confirm(`Delete "${name}" with its ${topics.length} topic${topics.length===1?'':'s'}, study material and videos${tests?` and ${tests} CEC test${tests===1?'':'s'}`:''}? This cannot be undone.`))return;state.tests=state.tests.filter(t=>t.subject!==name);removeTopics(topics.map(s=>s.id));toast(`${name} deleted. Your plan has been updated.`)}}
function topicAction(a,id){const s=findS(id);if(!s)return;if(a==='deadline')return act('deadline',id);if(a==='archive')return act('cancel',id);
if(a==='restore'){s.status='active';buildPlan();save();renderAll();toast('Topic restored and added back to planning')}
else if(a==='rename'){const v=prompt('Topic name',s.topic);if(v===null)return;const n=v.trim().slice(0,80);if(!n)return toast('Name cannot be empty');s.topic=n;state.tasks.forEach(t=>{if(String(t.subjectId)===String(s.id))t.topic=n});save();renderAll();toast('Topic renamed')}
else if(a==='delete'){if(!confirm(`Delete "${s.topic}" from ${s.subject}? Its study material and videos are removed too.`))return;removeTopics([s.id]);toast('Topic deleted. Your plan has been updated.')}}
function bindDynamic(){$$('[data-task]').forEach(b=>b.onclick=()=>toggleTask(b.dataset.task));$$('[data-focus]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(x=>x.id===b.dataset.focus);if(t){state.focusId=t.id;resetTimer();save();renderAll();navigate('focus')}});$$('[data-delete]').forEach(b=>b.onclick=()=>deleteTopic(b.dataset.delete));$$('[data-rating]').forEach(i=>i.oninput=()=>{const s=findS(i.dataset.rating);if(s){s.rating=clamp(Number(i.value),1,5);save();renderProgress();renderSubjects()}});$$('[data-topicdone]').forEach(b=>b.onclick=()=>{const s=findS(b.dataset.topicdone);if(s){s.completed=!s.completed;save();renderAll()}})}

