$('#menuBtn').onclick=()=>{const open=$('#sidebar').classList.toggle('open');$('#menuBtn').setAttribute('aria-expanded',String(open))};$$('.nav').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate(b.dataset.go)});$('#time').oninput=e=>{state.time=clamp(Number(e.target.value),30,480);save();renderDashboard();renderPlanner();renderFocus()};$('#energy').onclick=e=>{const v=e.target.closest('[data-v]')?.dataset.v;if(v){state.energy=v;if(state.tasks.length)generatePlan(true);else{save();renderPlanner();renderFocus()}}};$('#modes').onclick=e=>{const v=e.target.closest('[data-mode]')?.dataset.mode;if(v){state.mode=v;if(state.tasks.length)generatePlan(true);else{save();renderPlanner()}}};$('#time').onchange=()=>{if(state.tasks.length)generatePlan(true)};$('#generate').onclick=()=>generatePlan();$('#resetPlan').onclick=()=>{state.tasks=[];state.focusId=null;save();renderAll();toast('Plan reset')};$('#addTopic').onclick=addTopic;$('#addTest').onclick=()=>addTest();$$('.modal .close').forEach(b=>b.onclick=()=>closeModal(b.closest('.modal')));$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m)}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){const m=$$('.modal.open').pop();if(m)closeModal(m)}});
$('#topicForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),exam=String(f.get('exam'));if(exam&&exam<todayISO())return toast('Choose today or a future exam date');const subject=String(f.get('subject')).trim(),topic=String(f.get('topic')).trim();state.subjects.push(normSubject({id:`s-${Date.now()}`,subject,topic,exam,difficulty:Number(f.get('difficulty')),confidence:Number(f.get('confidence')),rating:Number(f.get('confidence'))+1,last:Date.now()}));e.currentTarget.reset();closeModal($('#modal'));buildPlan();save();renderAll();toast('Added. Your plan has been updated.')};
$('#testForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.currentTarget),max=Number(f.get('max')),obt=f.get('obtained')===''?null:Number(f.get('obtained'));if(!max||obt!==null&&(obt<0||obt>max))return toast('Check marks obtained against max marks');const item={id:e.currentTarget.dataset.edit||`t-${Date.now()}`,subject:String(f.get('subject')),name:String(f.get('name')).trim(),date:String(f.get('date')),max,obtained:obt,weight:Number(f.get('weight'))};if(!item.name||!item.date||item.weight<=0)return toast('Complete all test fields');const idx=state.tests.findIndex(t=>t.id===item.id),prev=idx>=0?state.tests[idx]:null;if(idx>=0)state.tests[idx]=item;else state.tests.push(item);closeModal($('#testModal'));buildPlan();save();renderAll();toast(idx>=0?'CEC test updated':'CEC test added');const pct=item.obtained===null?0:item.obtained/item.max*100,had=prev&&prev.obtained!==null&&prev.obtained/prev.max*100>80;if(pct>80&&!had)celebrate(`${Math.round(pct)}% in ${item.name}!`,'Above 80%. Fantastic work!',['🏆','🎉','💯','⭐','🔥'])};
$('#saveName').onclick=()=>{state.name=$('#name').value.trim().slice(0,40);save();renderAll();toast(state.name?'Profile saved':'Profile set to Guest')};$('#textSize').onclick=e=>{const v=e.target.closest('[data-ts]')?.dataset.ts;if(SIZES.includes(v)){state.textSize=v;save();applyTextSize()}};$('#themeChoices').onclick=e=>{const v=e.target.closest('[data-theme]')?.dataset.theme;if(v){state.theme=v;save();applyTheme();renderAll()}};$('#themeToggle').onclick=()=>{state.theme=effectiveTheme()==='dark'?'light':'dark';save();applyTheme();renderAll()};$('#avatarUpload').onchange=e=>{const file=e.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/'))return toast('Choose an image');if(file.size>1.5*1024*1024)return toast('Photo must be under 1.5 MB');const r=new FileReader();r.onload=()=>{state.avatar=r.result;save();renderProfile();renderSettings();toast('Profile photo saved')};r.readAsDataURL(file)};$('#removeAvatar').onclick=()=>{state.avatar=null;save();renderProfile();renderSettings();toast('Profile photo removed')};$('#clearData').onclick=()=>{if(!confirm('Reset all planner data, materials, videos and CEC tests?'))return;localStorage.setItem(STORAGE_KEY,JSON.stringify(migrateState({demoWeekSeededV2:true})));location.reload()};$('#startTimer').onclick=startPauseTimer;$('#resetTimer').onclick=resetTimer;
$('#targetScore').oninput=e=>{state.targetScore=clamp(Number(e.target.value)||80,1,100);save();renderCEC()};$('#trendSubject').onchange=e=>drawTrend(e.target.value);$('#materialSearch').oninput=renderMaterials;$('#materialSubject').onchange=renderMaterials;$('#videoSearch').oninput=renderVideos;$('#youtubeSearchGlobal').onclick=()=>window.open(ytSearch('','study topics'),'_blank','noopener');$('#addMaterialGlobal').onclick=addMaterialGlobal;$('#addVideoGlobal').onclick=addVideoGlobal;

document.addEventListener('click',e=>{const fb=e.target.closest('[data-fb]');if(fb)return feedback(fb.dataset.fbtask,fb.dataset.fb);if(e.target.closest('[data-more]'))return morePlan();const go=e.target.closest('[data-go]');if(go){e.preventDefault();navigate(go.dataset.go);return}const a=e.target.closest('[data-act]');if(a)return act(a.dataset.act,a.dataset.id);const wsBtn=e.target.closest('[data-ws]');if(wsBtn)return openWS(wsBtn.dataset.ws,wsBtn.dataset.tab);const watchBtn=e.target.closest('[data-watch]');if(watchBtn){const s=findS(watchBtn.dataset.watch),v=s?.videos.find(x=>x.type==='video'&&ytId(x.url));return v?openVideo(v):window.open(ytSearch(s?.subject||'',s?.topic||''),'_blank','noopener')}const g=e.target.closest('[data-globalopen]');if(g)return openGlobalMaterial(g.dataset.globalopen,g.dataset.subject);const gv=e.target.closest('[data-globalvideo]');if(gv)return openGlobalVideo(gv.dataset.globalvideo,gv.dataset.subject);const et=e.target.closest('[data-edittest]');if(et){const t=state.tests.find(x=>x.id===et.dataset.edittest);if(t)addTest(t);return}const dt=e.target.closest('[data-deltest]');if(dt)return deleteTest(dt.dataset.deltest)});
document.addEventListener('change',e=>{const o=e.target.closest('[data-only]');if(o){state.onlySubject=o.value;if(state.tasks.length)generatePlan(true);else{save();renderPlanner()}return}});
$('#wsSubject').onchange=e=>{const name=e.target.value,first=state.subjects.find(x=>x.subject===name);if(first){ws.id=first.id;ws.edit=null;renderWS()}};$('#wsTabs').onclick=e=>{const t=e.target.closest('[data-tab]')?.dataset.tab;if(t){ws.tab=t;ws.edit=null;renderWS()}};$('#wsBody').addEventListener('change',e=>{if(e.target.id==='matType')syncType()});$('#wsBody').addEventListener('submit',e=>{e.preventDefault();ws.tab==='material'?saveMaterial(e.target):saveVideo(e.target)});$('#wsBody').addEventListener('click',e=>{const b=e.target.closest('[data-open],[data-edit],[data-del],[data-cancel]');if(!b)return;if(b.hasAttribute('data-cancel')){ws.edit=null;renderWS();return}const s=findS(ws.id);if(!s)return;const key=ws.tab==='material'?'materials':'videos',id=b.dataset.open||b.dataset.edit||b.dataset.del,it=s[key].find(x=>x.id===id);if(!it)return;if(b.dataset.open)return ws.tab==='material'?openMaterial(it):openVideo(it);if(b.dataset.edit){ws.edit=id;renderWS();return}if(b.dataset.del){if(!confirm(`Delete "${it.title}"?`))return;if(it.type==='file')idb.del(it.id).catch(()=>{});s[key]=s[key].filter(x=>x.id!==id);ws.edit=null;save();renderWS();renderAll();toast('Deleted')}});
window.addEventListener('resize',()=>{if($('#cec').classList.contains('active'))drawTrend($('#trendSubject').value)});window.matchMedia('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(state.theme==='system'){applyTheme();renderAll()}});window.addEventListener('beforeunload',()=>clearInterval(timer.id));

$$('#pomoModes [data-pm]').forEach(b=>b.onclick=()=>setMode(b.dataset.pm));
$('#pomoDone').onclick=()=>{const t=focusTask();if(!t)return toast('Generate a plan first');toggleTask(t.id)};
$$('[data-pset]').forEach(i=>i.onchange=()=>{const k=i.dataset.pset;state.pomo[k]=i.type==='checkbox'?i.checked:clamp(Number(i.value)||1,1,k==='every'?8:120);if(k==='every')state.pomo.every=Math.max(2,state.pomo.every);save();if(!timer.running&&PM[k])setMode(timer.mode);renderPomoStats()});
// ---- Visual effects: page glow follows the cursor, cards get a spotlight, buttons ripple. Off for reduced motion. ----
if(!calm){let raf=0;document.addEventListener('pointermove',e=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;const r=document.documentElement.style;r.setProperty('--gx',e.clientX+'px');r.setProperty('--gy',e.clientY+'px');const c=e.target.closest?.('.panel,.stat,.subject,.planCard,.cecCard,.libraryItem,.recommend,.hero,.cecHero');if(c){const b=c.getBoundingClientRect();c.style.setProperty('--mx',e.clientX-b.left+'px');c.style.setProperty('--my',e.clientY-b.top+'px')}})});
document.addEventListener('pointerdown',e=>{const d=document.createElement('span');d.className='tapRing';d.style.cssText=`left:${e.clientX}px;top:${e.clientY}px`;document.body.appendChild(d);setTimeout(()=>d.remove(),380)})}

$('#goalInput').onchange=e=>{state.goal=clamp(Number(e.target.value)||120,15,720);save();renderDashExtras()};
$('#pomoNotes').oninput=e=>{state.notes=e.target.value.slice(0,5000);save()};
$('#exportBackup').onclick=exportBackup;$('#importFile').onchange=e=>{const f=e.target.files?.[0];if(f)importBackup(f);e.target.value=''};
// ---- Editable must-do list (state.mustDo) and dashboard shortcuts ----
const mdAdd=text=>{text=String(text).trim().slice(0,120);if(!text)return false;if(state.mustDo.length>=20){toast('Finish or clear some items first');return false}state.mustDo.push({id:`md-${Date.now()}-${Math.random().toString(36).slice(2,6)}`,text,done:false});return true};
$('#mdAdd').onclick=()=>{if(mdAdd($('#mdNew').value)){$('#mdNew').value='';save();renderDashExtras()}};
$('#mdNew').onkeydown=e=>{if(e.key==='Enter')$('#mdAdd').click()};
$('#mdSuggest').onclick=()=>{const have=new Set(state.mustDo.map(x=>x.text)),picks=state.tasks.filter(t=>!t.done).map(t=>t.topic).filter(t=>!have.has(t)).slice(0,3);if(!picks.length)return toast('Generate a plan first, or type your own');picks.forEach(mdAdd);save();renderDashExtras();toast('Added from your plan. Edit them any way you like.')};
$('#mdClear').onclick=()=>{state.mustDo=state.mustDo.filter(x=>!x.done);save();renderDashExtras()};
$('#mustDo').addEventListener('click',e=>{const t=e.target.closest('[data-mdtoggle]'),d=e.target.closest('[data-mddel]');if(t){const x=state.mustDo.find(i=>i.id===t.dataset.mdtoggle);if(x){x.done=!x.done;save();renderDashExtras();if(x.done){if(state.mustDo.every(i=>i.done))celebrate('All must-dos done!','Your list is clear. Enjoy the win.',['🎯','🎉','✅','🌟','👏']);else{burst();toast('✅ Nice! One less thing to do.')}}}}else if(d){state.mustDo=state.mustDo.filter(i=>i.id!==d.dataset.mddel);save();renderDashExtras()}});
$('#mustDo').addEventListener('change',e=>{const i=e.target.closest('[data-mdedit]'),x=i&&state.mustDo.find(y=>y.id===i.dataset.mdedit);if(!x)return;const v=i.value.trim().slice(0,120);if(v)x.text=v;else state.mustDo=state.mustDo.filter(y=>y!==x);save();renderDashExtras()});
